// Device controls.
const knobDefs=[['depth','DCW','line',0,1,'percent'],['attack','ATTACK','amp',.005,4,'time'],['decay','DECAY','amp',.05,5,'time'],['sustain','SUSTAIN','amp',0,1,'percent'],['release','RELEASE','amp',.05,8,'time'],['brightness','TONE','patch',0,1,'percent'],['reverb','CHAMBER','patch',0,1,'percent'],['delay','ECHO','patch',0,.8,'percent']];
function knobGet(k){let l=patch.lines[activeLine];return k[2]==='line'?l[k[0]]:k[2]==='patch'?patch[k[0]]:k[0]==='attack'?l.amp.p[0][0]:k[0]==='decay'?l.amp.p[1][0]+l.amp.p[2][0]:k[0]==='sustain'?l.amp.p[l.amp.s][1]:l.amp.p.slice(l.amp.s+1).reduce((a,p)=>a+p[0],0)}
function knobSet(k,v){let l=patch.lines[activeLine];v=clamp(v,k[3],k[4]);if(k[2]==='line')l[k[0]]=v;else if(k[2]==='patch')patch[k[0]]=v;else{let a=knobGet(knobDefs[1]),d=knobGet(knobDefs[2]),s=knobGet(knobDefs[3]),r=knobGet(knobDefs[4]);if(k[0]==='attack')a=v;else if(k[0]==='decay')d=v;else if(k[0]==='sustain')s=v;else r=v;l.amp=ampEnv(a,d,s,r)}dirtyPatch();updateKnob(k)}
function toNorm(k,v){return k[5]==='time'?Math.sqrt((v-k[3])/(k[4]-k[3])):(v-k[3])/(k[4]-k[3])}function fromNorm(k,v){return k[3]+(k[4]-k[3])*(k[5]==='time'?v*v:v)}
function drawKnob(el,norm){let canvas=el.querySelector('canvas');if(!canvas){canvas=document.createElement('canvas');canvas.width=48;canvas.height=48;canvas.style.cssText='width:100%;height:100%;display:block;image-rendering:pixelated;pointer-events:none';el.append(canvas)}let g=canvas.getContext('2d');g.clearRect(0,0,48,48);for(let i=0;i<=10;i++){let angle=(-225+i*27)*Math.PI/180,x=Math.round(24+Math.cos(angle)*22),y=Math.round(24+Math.sin(angle)*22);g.fillStyle=i<=norm*10?'#aeb995':'#596d69';g.fillRect(x-1,y-1,2,2)}for(let y=5;y<46;y++)for(let x=5;x<46;x++){let dx=x-24,dy=y-24,r=Math.sqrt(dx*dx+dy*dy);if(Math.sqrt((x-26)**2+(y-27)**2)<17){g.fillStyle='#080f14';g.fillRect(x,y,1,1)}if(r<17){let light=clamp(Math.floor((19-r)/5+(-dx-dy)/12),0,5);g.fillStyle=['#101b21','#1a272c','#29373a','#3d4a49','#56615a','#6d7666'][light];if(r>15&&dx+dy<0)g.fillStyle='#788375';g.fillRect(x,y,1,1)}}let angle=(-225+norm*270)*Math.PI/180;g.strokeStyle='#d9d9aa';g.lineWidth=2;g.beginPath();g.moveTo(Math.round(24+Math.cos(angle)*9),Math.round(24+Math.sin(angle)*9));g.lineTo(Math.round(24+Math.cos(angle)*14),Math.round(24+Math.sin(angle)*14));g.stroke()}
function updateKnob(k){let v=knobGet(k),el=$('knob_'+k[0]);if(!el)return;drawKnob(el,clamp(toNorm(k,v),0,1));el.setAttribute('aria-valuenow',v.toFixed(3));el.setAttribute('aria-valuetext',k[5]==='time'?v.toFixed(2)+' секунд':Math.round(v*100)+'%');$('out_'+k[0]).textContent=k[5]==='time'?v.toFixed(2)+'s':Math.round(v*100)+'%'}
function renderKnobs(){let wrap=$('knobs');wrap.innerHTML='';knobDefs.forEach(k=>{let unit=document.createElement('div');unit.className='knobunit';unit.innerHTML=`<label>${k[1]}</label><div class="knob" id="knob_${k[0]}" role="slider" tabindex="0" aria-label="${k[1]}" aria-valuemin="${k[3]}" aria-valuemax="${k[4]}"></div><output id="out_${k[0]}"></output>`;wrap.append(unit);let el=$('knob_'+k[0]),startY=0,startN=0;el.onpointerdown=e=>{el.setPointerCapture(e.pointerId);startY=e.clientY;startN=toNorm(k,knobGet(k));e.preventDefault()};el.onpointermove=e=>{if(el.hasPointerCapture(e.pointerId)){let v=clamp(startN+(startY-e.clientY)/(e.shiftKey?1000:180),0,1);knobSet(k,fromNorm(k,v))}};el.onwheel=e=>{e.preventDefault();knobSet(k,fromNorm(k,clamp(toNorm(k,knobGet(k))+(e.deltaY<0?1:-1)*(e.shiftKey?.002:.02),0,1)))};el.onkeydown=e=>{if(['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].includes(e.key)){e.preventDefault();knobSet(k,fromNorm(k,clamp(toNorm(k,knobGet(k))+(['ArrowUp','ArrowRight'].includes(e.key)?1:-1)*(e.shiftKey?.002:.02),0,1)))}};updateKnob(k)})}
function shiftOct(d){releaseAll();octave=clamp(octave+d,-2,2);$('octLabel').textContent=`${noteName(36+12*octave)} — ${noteName(84+12*octave)} · OCT ${octave>=0?'+':''}${octave}`;toast('Октава '+(octave>=0?'+':'')+octave)}
const typingMap={KeyA:0,KeyW:1,KeyS:2,KeyE:3,KeyD:4,KeyF:5,KeyT:6,KeyG:7,KeyY:8,KeyH:9,KeyU:10,KeyJ:11,KeyK:12,KeyO:13,KeyL:14,KeyP:15,Semicolon:16};
function keyGlow(n,v){let k=document.querySelector('.key[data-note="'+n+'"]');if(k)k.classList.toggle('down',v)}
window.addEventListener('keydown',async e=>{if(document.body.classList.contains('intro-open')||e.ctrlKey||e.metaKey||e.altKey||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('.veil.open')||editorHasFocus())return;if(e.target.tagName==='BUTTON'&&e.code==='Space')return;if(e.repeat){if(e.code==='Space'||typingMap[e.code]!==undefined)e.preventDefault();return}if(e.code==='Space'){e.preventDefault();toggleAll();return}if(e.code==='KeyZ'){shiftOct(-1);return}if(e.code==='KeyX'){shiftOct(1);return}if(typingMap[e.code]!==undefined){e.preventDefault();let n=48+typingMap[e.code];heldKeys.set(e.code,{n,id:null});keyGlow(n,true);if(!await startAudio())return;let h=heldKeys.get(e.code);if(h)h.id=noteOn(n+octave*12)}});
window.addEventListener('keyup',e=>{let h=heldKeys.get(e.code);if(h){if(h.id)noteOff(h.id);keyGlow(h.n,false);heldKeys.delete(e.code)}});window.addEventListener('blur',releaseAll);document.addEventListener('visibilitychange',()=>{if(document.hidden){releaseAll();}});
function bindWheel(el,kind){let y,v;const set=value=>{if(kind==='bend'){bend=clamp(value,-2,2);node?.port.postMessage({type:'bend',value:bend});el.setAttribute('aria-valuenow',bend.toFixed(2))}else{mod=clamp(value,0,1);node?.port.postMessage({type:'mod',value:mod});el.setAttribute('aria-valuenow',mod.toFixed(2))}el.style.backgroundPositionY=((kind==='bend'?bend:mod)*12)+'px'};el.onpointerdown=e=>{el.setPointerCapture(e.pointerId);y=e.clientY;v=kind==='bend'?bend:mod};el.onpointermove=e=>{if(el.hasPointerCapture(e.pointerId))set(v+(y-e.clientY)/(kind==='bend'?35:80))};el.onpointerup=el.onpointercancel=()=>{if(kind==='bend')set(0)};el.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();set((kind==='bend'?bend:mod)+(e.key==='ArrowUp'?.1:-.1))}if(e.key==='Home'||e.key==='Escape')set(0)}}
// Eight-stage envelope editor.
let envKind='amp';function openEnv(kind){envKind=kind;$('envTitle').textContent=`LINE ${activeLine+1} / ${kind==='amp'?'DCA · AMPLITUDE':kind==='dcw'?'DCW · PHASE DEPTH':'DCO · PITCH'}`;let env=patch.lines[activeLine][kind];$('envSustain').innerHTML=Array.from({length:7},(_,i)=>`<option value="${i}">STEP ${i+1}</option>`).join('');$('envSustain').value=env.s;$('envGrid').innerHTML='';env.p.forEach((p,i)=>{let d=document.createElement('div');d.className='envstage';d.innerHTML=`<b>${i+1}</b><label>TIME / s</label><input type="number" min="0.005" max="15" step="0.01" value="${p[0].toFixed(3)}" data-env="${i}" data-part="0"><label>LEVEL</label><input type="range" min="0" max="1" step="0.01" value="${p[1]}" data-env="${i}" data-part="1"><output>${p[1].toFixed(2)}</output>`;$('envGrid').append(d)});$('envGrid').querySelectorAll('input').forEach(inp=>{inp.oninput=()=>{let i=+inp.dataset.env,part=+inp.dataset.part,val=Number(inp.value);if(!Number.isFinite(val))return;env.p[i][part]=clamp(val,part===0?.005:0,part===0?15:1);if(kind==='amp')env.p[7][1]=0;if(part===1)inp.nextElementSibling.textContent=env.p[i][1].toFixed(2);dirtyPatch();drawEnv();renderKnobs()}});$('envSustain').onchange=()=>{env.s=+$('envSustain').value;dirtyPatch();drawEnv()};drawEnv();openModal('envModal')}
function drawEnv(){let c=$('envGraph'),g=c.getContext('2d'),e=patch.lines[activeLine][envKind],total=e.p.reduce((s,p)=>s+p[0],0),x=12,y=118;g.fillStyle='#101b19';g.fillRect(0,0,800,130);g.strokeStyle='#2b4437';for(let i=0;i<8;i++){g.beginPath();g.moveTo(i*100,0);g.lineTo(i*100,130);g.stroke()}g.strokeStyle='#bfca8b';g.lineWidth=2;g.beginPath();g.moveTo(x,y);for(let i=0;i<8;i++){x+=e.p[i][0]/total*776;y=118-e.p[i][1]*105;g.lineTo(x,y)}g.stroke();x=12;for(let i=0;i<8;i++){x+=e.p[i][0]/total*776;y=118-e.p[i][1]*105;g.fillStyle=i===e.s?'#e5ad69':'#b0c299';g.fillRect(x-3,y-3,6,6)}}
function openModal(id){releaseAll();$(id).classList.add('open')}document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.veil').classList.remove('open'));document.querySelectorAll('.veil').forEach(v=>v.addEventListener('pointerdown',e=>{if(e.target===v)v.classList.remove('open')}));window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.veil.open').forEach(v=>v.classList.remove('open'));releaseAll()}});
function renderLibrary(filter='Все'){let cats=['Все',...new Set(patches.map(p=>p.cat))];$('patchFilters').innerHTML='';cats.forEach(cat=>{let b=document.createElement('button');b.textContent=cat;b.classList.toggle('active',filter===cat);b.onclick=()=>renderLibrary(cat);$('patchFilters').append(b)});$('patchGrid').innerHTML='';patches.forEach((p,i)=>{if(filter!=='Все'&&p.cat!==filter)return;let b=document.createElement('button');b.className='patchcard';b.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><strong></strong><small></small>`;b.querySelector('strong').textContent=p.name;b.querySelector('small').textContent=p.desc;b.classList.toggle('active',i===patchIndex);b.onclick=()=>{selectPatch(i);$('libraryModal').classList.remove('open');toast(p.name)};$('patchGrid').append(b)})}
function makeControl(label,value,min,max,step,fn){let l=document.createElement('label');let span=document.createElement('span');span.textContent=label;let i=document.createElement('input');i.type='range';Object.assign(i,{min,max,step,value});let o=document.createElement('output');o.textContent=Number(value).toFixed(2);i.oninput=()=>{fn(+i.value);o.textContent=(+i.value).toFixed(2);dirtyPatch();renderKnobs()};l.append(span,i,o);return l}
function renderFX(){let g=$('fxGrid');g.innerHTML='';[['CHAMBER','reverb',0,1],['DELAY MIX','delay',0,.8],['DELAY TIME / s','delayTime',.05,1.5],['CHORUS','chorus',0,1],['PREAMP','drive',0,1],['TONE','brightness',0,1],['VIBRATO DEPTH','vibrato',0,.02],['VIBRATO Hz','vibRate',.2,10],['RING MIX','ring',0,1],['NOISE MIX','noise',0,.2],['PITCH ENV / st','pitchDepth',0,48]].forEach(([n,k,a,b])=>g.append(makeControl(n,patch[k],a,b,k==='vibrato'?.0005:.01,v=>patch[k]=v)));let w=$('waveGrid');w.innerHTML='';patch.lines.forEach((l,i)=>{let box=document.createElement('div');box.style.cssText='border:1px solid #51615b;padding:12px';box.innerHTML=`<div class="sectioncap">LINE ${i+1}</div>`;for(let key of ['wave','wave2']){let lab=document.createElement('label');lab.style.cssText='display:flex;justify-content:space-between;margin:8px 0';lab.textContent=key==='wave'?'WAVE 1':'WAVE 2';let sel=document.createElement('select');if(key==='wave2'){let op=new Option('OFF','-1');sel.add(op)}waveNames.forEach((n,j)=>sel.add(new Option(n,j)));sel.value=l[key];sel.onchange=()=>{l[key]=+sel.value;dirtyPatch()};lab.append(sel);box.append(lab)}box.append(makeControl('LEVEL',l.level,0,1,.01,v=>l.level=v));let lab=document.createElement('label');lab.textContent='OCTAVE';let s=document.createElement('select');[-2,-1,0,1,2].forEach(v=>s.add(new Option(v>=0?'+'+v:v,v)));s.value=l.oct;s.onchange=()=>{l.oct=+s.value;dirtyPatch()};lab.append(s);box.append(lab);w.append(box)})}
